static float Cross(Vector2 a,Vector2 b,Vector2 p)=>(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x);
static float Edge(Vector2 p,Vector2[] line,out float side){float d=float.MaxValue;side=0;for(int i=0;i<line.Length-1;i++){var e=line[i+1]-line[i];var q=line[i]+e*Mathf.Clamp01(Vector2.Dot(p-line[i],e)/e.sqrMagnitude);float distance=Vector2.Distance(p,q);if(distance<d){d=distance;side=Vector2.Dot(p-q,new Vector2(e.y,-e.x).normalized);}}return d;}
static bool Park(Vector2 p,Bounds b)=>p.x>=b.min.x&&p.x<=b.max.x&&p.y>=b.min.z&&p.y<=b.max.z;
static bool TrianglePark(Vector3 a,Vector3 b,Vector3 c,Bounds bounds){if(Mathf.Max(a.x,Mathf.Max(b.x,c.x))<bounds.min.x||Mathf.Min(a.x,Mathf.Min(b.x,c.x))>bounds.max.x||Mathf.Max(a.z,Mathf.Max(b.z,c.z))<bounds.min.z||Mathf.Min(a.z,Mathf.Min(b.z,c.z))>bounds.max.z)return false;return true;}
static float Height(TerrainData data,Vector3 origin,Vector3 p)=>origin.y+data.GetInterpolatedHeight(Mathf.Clamp01((p.x-origin.x)/data.size.x),Mathf.Clamp01((p.z-origin.z)/data.size.z));
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=scene.GetRootGameObjects();var group=roots.Single(g=>g.name=="Coastal Rocky Terrain");var terrain=group.GetComponentInChildren<Terrain>();var data=terrain.terrainData;var before=UnityEngine.Object.Instantiate(data);string backup=Dir+"/Before Gap and Parking Repair.asset";if(!AssetDatabase.LoadAssetAtPath<TerrainData>(backup))AssetDatabase.CreateAsset(UnityEngine.Object.Instantiate(data),backup);
var parking=roots.SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Single(r=>r.name=="Parking_Material #47_0");var parkingBounds=parking.bounds;parkingBounds.Expand(new Vector3(5,0,5));log.AppendLine("Protected parking="+parkingBounds);
var lines=File.ReadAllLines("FinalEnvironmentRoadReview/CoastalSnappedEdge.txt").Select(s=>{var v=s.Trim('(',')').Split(',');return new Vector2(float.Parse(v[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(v[1],System.Globalization.CultureInfo.InvariantCulture));}).ToList();if(Vector2.Distance(lines[lines.Count-2],lines.Last())>35)lines.Insert(lines.Count-1,new Vector2(lines.Last().x,lines[lines.Count-2].y));for(int i=0;i<lines.Count;i++){var point=lines[i];if(point.y>=parkingBounds.min.z-10&&point.y<=parkingBounds.max.z+10)lines[i]=new Vector2(Mathf.Max(point.x,parkingBounds.max.x+1),point.y);}var line=lines.ToArray();
var origin=terrain.transform.position;var size=data.size;var heights=data.GetHeights(0,0,513,513);var oldMask=data.GetHoles(0,0,512,512);var mask=new bool[512,512];var roadHeights=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++)roadHeights[z,x]=float.MaxValue;
var read=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic);var roadRoot=roots.Single(g=>g.name=="Track Roads");foreach(var f in roadRoot.GetComponentsInChildren<MeshFilter>(true)){var renderer=f.GetComponent<MeshRenderer>();if(!renderer||!renderer.sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name.StartsWith("City PNG"))))continue;var meshData=read.Invoke(null,new object[]{f.sharedMesh});var p=((Vector3[])meshData.GetType().GetField("p").GetValue(meshData)).Select(f.transform.TransformPoint).ToArray();var ids=(int[])meshData.GetType().GetField("ids").GetValue(meshData);for(int i=0;i<ids.Length;i+=3){var a=p[ids[i]];var b=p[ids[i+1]];var c=p[ids[i+2]];if(Mathf.Abs(a.y-b.y)>1||Mathf.Abs(a.y-c.y)>1)continue;var av=new Vector2(a.x,a.z);var bv=new Vector2(b.x,b.z);var cv=new Vector2(c.x,c.z);float den=Cross(av,bv,cv);if(Mathf.Abs(den)<.001f)continue;int x0=Mathf.Max(0,Mathf.FloorToInt((Mathf.Min(a.x,Mathf.Min(b.x,c.x))-origin.x)/size.x*512)-1),x1=Mathf.Min(512,Mathf.CeilToInt((Mathf.Max(a.x,Mathf.Max(b.x,c.x))-origin.x)/size.x*512)+1);int z0=Mathf.Max(0,Mathf.FloorToInt((Mathf.Min(a.z,Mathf.Min(b.z,c.z))-origin.z)/size.z*512)-1),z1=Mathf.Min(512,Mathf.CeilToInt((Mathf.Max(a.z,Mathf.Max(b.z,c.z))-origin.z)/size.z*512)+1);for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++){var q=new Vector2(origin.x+x/512f*size.x,origin.z+z/512f*size.z);float u=Cross(q,bv,cv)/den,v=Cross(av,q,cv)/den,w=1-u-v;if(u<-.008f||v<-.008f||w<-.008f)continue;roadHeights[z,x]=Mathf.Min(roadHeights[z,x],u*a.y+v*b.y+w*c.y);}}}
var shore=roadRoot.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="Outer_MEsh");var probeObject=new GameObject("Temporary coastal ground probe"){hideFlags=HideFlags.HideAndDontSave};probeObject.transform.SetPositionAndRotation(shore.transform.position,shore.transform.rotation);probeObject.transform.localScale=shore.transform.lossyScale;var collider=probeObject.AddComponent<MeshCollider>();collider.sharedMesh=shore.sharedMesh;bool oldBackfaces=Physics.queriesHitBackfaces;Physics.queriesHitBackfaces=true;int filled=0,protectedCells=0;
for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=origin.x+(x+.5f)/512*size.x,wz=origin.z+(z+.5f)/512*size.z;var p=new Vector2(wx,wz);float distance=Edge(p,line,out float side);bool road=roadHeights[z,x]!=float.MaxValue||roadHeights[z+1,x+1]!=float.MaxValue;bool land=distance<=46&&collider.Raycast(new Ray(new Vector3(wx,140,wz),Vector3.down),out var hit,180)&&hit.point.y>=23.5f;bool allowed=land&&(oldMask[z,x]||side>=-.5f&&distance<46);if(Park(p,parkingBounds)||road){allowed=false;protectedCells++;}mask[z,x]=allowed;if(allowed&&!oldMask[z,x])filled++;}
Physics.queriesHitBackfaces=oldBackfaces;UnityEngine.Object.DestroyImmediate(probeObject);
for(int z=0;z<513;z++)for(int x=0;x<513;x++){float wx=origin.x+x/512f*size.x,wz=origin.z+z/512f*size.z;var p=new Vector2(wx,wz);int xx=Mathf.Min(x,511),zz=Mathf.Min(z,511);float distance=Edge(p,line,out float side);float y=heights[z,x]*size.y;if(mask[zz,xx]&&!oldMask[zz,xx]){float rise=Mathf.SmoothStep(0,1,Mathf.InverseLerp(1,30,distance));float fall=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(36,45,distance));y=27.35f+(17+Mathf.PerlinNoise(wx/29+17,wz/29+36)*16)*rise*fall;float sum=0;int count=0;for(int j=-3;j<=3;j++)for(int k=-3;k<=3;k++){int nx=x+k,nz=z+j;if(nx<0||nz<0||nx>=512||nz>=512||!oldMask[nz,nx])continue;sum+=before.GetHeight(nx,nz);count++;}if(count>0)y=Mathf.Lerp(y,sum/count,.78f);}
if(Park(p,parkingBounds))y=26.7f;else if(wz>=parkingBounds.min.z-8&&wz<=parkingBounds.max.z+8&&wx>parkingBounds.max.x){float back=wx-parkingBounds.max.x;y=Mathf.Min(y,27.35f+36*Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,26,back)));}
if(roadHeights[z,x]!=float.MaxValue)y=Mathf.Min(y,roadHeights[z,x]-.35f);heights[z,x]=Mathf.Max(.01f,y/size.y);}
data.SetHeights(0,0,heights);data.SetHoles(0,0,mask);terrain.Flush();
int removed=0;var seen=new HashSet<Mesh>();foreach(var f in group.GetComponentsInChildren<MeshFilter>(true)){var mesh=f.sharedMesh;if(!mesh||!seen.Add(mesh))continue;var p=mesh.vertices;bool plants=f.transform.parent&&(f.transform.parent.name.StartsWith("Pine_")||f.transform.parent.name.StartsWith("Shrub_"));int stride=f.name=="Detailed"?12:8;if(plants){for(int start=0;start<p.Length;start+=stride){int count=Mathf.Min(stride,p.Length-start);var center=Vector3.zero;for(int j=0;j<count;j++)center+=f.transform.TransformPoint(p[start+j]);center/=count;float delta=Height(data,origin,center)-Height(before,origin,center);for(int j=0;j<count;j++)p[start+j].y+=delta;}}else for(int i=0;i<p.Length;i++){var world=f.transform.TransformPoint(p[i]);p[i].y+=Height(data,origin,world)-Height(before,origin,world);}var ids=mesh.triangles;var keep=new List<int>();for(int i=0;i<ids.Length;i+=3){var a=f.transform.TransformPoint(p[ids[i]]);var b=f.transform.TransformPoint(p[ids[i+1]]);var c=f.transform.TransformPoint(p[ids[i+2]]);if(TrianglePark(a,b,c,parkingBounds)){removed++;continue;}keep.AddRange(new[]{ids[i],ids[i+1],ids[i+2]});}mesh.vertices=p;mesh.triangles=keep.ToArray();if(!plants)mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);}UnityEngine.Object.DestroyImmediate(before);
var alpha=new float[512,512,3];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float u=(x+.5f)/512,v=(z+.5f)/512;float wx=origin.x+u*size.x,wz=origin.z+v*size.z;float slope=data.GetSteepness(u,v);float patch=Mathf.PerlinNoise(wx/15+13,wz/15+61);float grass=Mathf.Lerp(.58f,.88f,patch)*(1-.62f*Mathf.InverseLerp(42,72,slope));float soil=.08f+.1f*Mathf.PerlinNoise(wx/9+19,wz/9+37);alpha[z,x,1]=grass;alpha[z,x,2]=soil;alpha[z,x,0]=Mathf.Max(.02f,1-grass-soil);float sum=alpha[z,x,0]+grass+soil;for(int k=0;k<3;k++)alpha[z,x,k]/=sum;}data.SetAlphamaps(0,0,alpha);data.SetBaseMapDirty();terrain.Flush();EditorUtility.SetDirty(data);
foreach(var lod in group.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAssetAndConnect(group,Dir+"/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,parking.bounds.center+new Vector3(-65,120,-95),parking.bounds.center,"Terrain-Repaired-Parking"});capture.Invoke(null,new object[]{scene,new Vector3(365,130,680),new Vector3(333,28,568),"Terrain-Repaired-Corner"});capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Terrain-Repaired-Green-Road-Level"});log.AppendLine("SUCCESS filled coastal cells="+filled+"; protected road/parking cells="+protectedCells+"; removed rock/plant triangles over parking="+removed+"; parking buffer=2.5m; grassy coverage 58-88 percent on gentler slopes, exposed rock retained on cliffs; scene and prefab saved.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalLayoutRepairReport.txt",log.ToString());}}
